options.getOption:
// Which satellite saw the detections, split into day and night overpasses.
// Five satellites carry two instruments: MODIS on Terra and Aqua (1 km
// pixels, since 2000) and VIIRS on Suomi-NPP, NOAA-20 and NOAA-21 (375 m,
// since 2012). Each one adds overpasses, so a count says as much about the
// fleet as about the fire. It follows every other filter but its own.
//
// Click a bar: keep that satellite only; click it again to clear. Click Day or
// Night in the legend: keep the other half only.
// @constants begin
const SAT = 'sat';
const DN = 'dn';
const ORDER = [
  ['Terra', 'MODIS'],
  ['Aqua', 'MODIS'],
  ['Suomi-NPP', 'VIIRS'],
  ['NOAA-20', 'VIIRS'],
  ['NOAA-21', 'VIIRS'],
];
const DAY = '#FFB357';
const NIGHT = '#8F3BB8';
// @constants end

const chart = context.panel.chart;
const theme = context.grafana.theme;
const location = context.grafana.locationService;
const muted = theme.colors.text.secondary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const sats = col('satellite');
const halves = col('daynight');
const counts = col('detections').map(Number);
const frp = col('frp_mw').map(Number);

const cell = (sat, half, values) => {
  let total = 0;
  sats.forEach((s, i) => {
    if (s === sat && halves[i] === half) {
      total += values[i];
    }
  });
  return total;
};

// ${sat} ${dn}: named literally so the panel redraws when either changes.
const pickedSat = context.grafana.replaceVariables('${' + SAT + '}');
const pickedHalf = context.grafana.replaceVariables('${' + DN + '}');

chart.off('click');
chart.on('click', (event) => {
  const sat = ORDER[event.dataIndex][0];
  location.partial({ ['var-' + SAT]: sat === pickedSat ? '' : sat }, true);
});
chart.off('legendselectchanged');
chart.on('legendselectchanged', (event) => {
  const day = event.selected.Day;
  const night = event.selected.Night;
  location.partial({ ['var-' + DN]: day && !night ? 'D' : night && !day ? 'N' : '' }, true);
});

const series = (name, half, color) => ({
  name,
  type: 'bar',
  stack: 'all',
  barWidth: '62%',
  cursor: 'pointer',
  itemStyle: { color },
  data: ORDER.map(([sat]) => ({
    value: cell(sat, half, counts),
    frp: cell(sat, half, frp),
    itemStyle: { color, opacity: pickedSat === '' || sat === pickedSat ? 1 : 0.3 },
  })),
});

return {
  animation: false,
  backgroundColor: 'transparent',
  legend: {
    top: 0,
    right: 8,
    textStyle: { color: muted },
    selected: { Day: pickedHalf !== 'N', Night: pickedHalf !== 'D' },
  },
  grid: { left: 8, right: 16, top: 28, bottom: 24, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) =>
      `<b>${ORDER[items[0].dataIndex].join(' · ')}</b><br/>` +
      items
        .map((it) => `${it.marker}${it.seriesName}: <b>${it.value.toLocaleString()}</b> detections, ${(it.data.frp / 1000).toFixed(1)} GW`)
        .join('<br/>'),
  },
  xAxis: {
    type: 'value',
    name: 'detections',
    nameLocation: 'middle',
    nameGap: 22,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: {
    type: 'category',
    inverse: true,
    data: ORDER.map(([sat, instrument]) => `${sat} · ${instrument}`),
    axisLabel: { color: theme.colors.text.primary },
    axisTick: { show: false },
  },
  series: [series('Day', 'D', DAY), series('Night', 'N', NIGHT)],
};

